-- Crop knowledge base shared by every X_Farm user. Generated from lib/crops.ts
-- by scripts/generate-crop-migration.ts; edit the source file, not this one.
create table if not exists public.crop_profiles (
  id text primary key check (id ~ '^[a-z][a-z-]{1,40}$'),
  profile jsonb not null check (jsonb_typeof(profile) = 'object'),
  source text,
  updated_at timestamptz not null default now()
);

alter table public.crop_profiles enable row level security;

drop policy if exists "Anyone can read crop profiles" on public.crop_profiles;
create policy "Anyone can read crop profiles" on public.crop_profiles
  for select to anon, authenticated
  using (true);

-- Read-only for app users; only migrations change the catalogue.
revoke all on public.crop_profiles from anon, authenticated, public;
grant usage on schema public to anon, authenticated;
grant select on public.crop_profiles to anon, authenticated;

insert into public.crop_profiles (id, profile, source) values
  ('tomato', '{"id":"tomato","emoji":"🍅","category":"fruiting","name":{"ro":"Roșie","en":"Tomato"},"scientificName":"Solanum lycopersicum","typeExample":{"ro":"Inimă de bou","en":"Beefsteak"},"ecocrop":{"code":1379,"scientificName":"Lycopersicon esculentum","tempOptimal":{"min":20,"max":27},"tempAbsolute":{"min":7,"max":35},"phOptimal":{"min":5.5,"max":6.8},"phAbsolute":{"min":5,"max":7.5},"cycleDays":{"min":70,"max":150},"killingTemp":null,"light":"clear skies"},"soilMoisture":{"min":42,"max":68},"humidity":{"min":50,"max":75},"light":{"min":400,"max":800},"soilTemperature":{"min":18,"max":26},"soilEc":{"min":1,"max":3},"irrigationBaseHours":24,"economics":{"yieldKgPerCycle":5,"cycleDays":120,"pricePerKg":12},"tip":{"ro":"Roșiile reacționează rău la udarea neregulată: constanța contează la fel de mult ca volumul de apă.","en":"Tomatoes respond badly to uneven watering. Consistency matters as much as the amount of water."},"learn":{"start":{"ro":"Semănați în interior cu 6–8 săptămâni înainte de răsădire, la 20–25 °C. Răsădiți când nopțile rămân peste 12 °C.","en":"Sow indoors 6–8 weeks before transplanting, at 20–25 °C. Transplant once nights stay above 12 °C."},"care":{"ro":"Palisați tulpina, îndepărtați copilii la soiurile nedeterminate și udați la bază, regulat.","en":"Stake the stem, remove side shoots on indeterminate types, and water regularly at the base."},"harvest":{"ro":"Recoltați când fructul are culoarea completă și cedează puțin la apăsare.","en":"Pick when the fruit has full colour and gives slightly when pressed."}},"symptoms":[{"sign":{"ro":"Pată închisă, adâncită, la baza fructului","en":"Dark, sunken patch at the bottom of the fruit"},"cause":{"ro":"Putregaiul apical, legat de obicei de udarea neregulată care limitează absorbția calciului","en":"Blossom end rot, usually linked to uneven watering limiting calcium uptake"},"action":{"ro":"Mențineți umiditatea solului constantă și verificați ca pH-ul să fie în interval.","en":"Keep soil moisture steady and check that pH is in range."}},{"sign":{"ro":"Florile cad fără să lege fruct","en":"Flowers dropping without setting fruit"},"cause":{"ro":"Adesea temperaturi prea mari sau prea mici","en":"Often temperatures that are too hot or too cold"},"action":{"ro":"Verificați temperatura aerului și aerisiți în orele calde.","en":"Check air temperature and improve ventilation during hot hours."}},{"sign":{"ro":"Frunzele de jos se îngălbenesc","en":"Lower leaves turning yellow"},"cause":{"ro":"Posibil deficit de azot, deși frunzele bătrâne se îngălbenesc și natural","en":"Possible nitrogen shortage, though ageing leaves also yellow naturally"},"action":{"ro":"Verificați EC-ul și fertilizați ușor dacă este scăzut.","en":"Check EC and feed lightly if it is low."}}],"airTemperature":{"min":20,"max":27},"soilPh":{"min":5.5,"max":6.8}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('pepper', '{"id":"pepper","emoji":"🫑","category":"fruiting","name":{"ro":"Ardei","en":"Pepper"},"typeExample":{"ro":"Kapia","en":"California Wonder"},"ecocrop":{"code":618,"scientificName":"Capsicum annuum","tempOptimal":{"min":17,"max":30},"tempAbsolute":{"min":8,"max":35},"phOptimal":{"min":5.5,"max":6.8},"phAbsolute":{"min":4.5,"max":7},"cycleDays":{"min":60,"max":180},"killingTemp":null,"light":"very bright"},"soilMoisture":{"min":35,"max":65},"humidity":{"min":45,"max":70},"light":{"min":350,"max":750},"soilTemperature":{"min":18,"max":27},"soilEc":{"min":1,"max":2.5},"irrigationBaseHours":30,"economics":{"yieldKgPerCycle":3,"cycleDays":120,"pricePerKg":15},"tip":{"ro":"Ardeii iubesc căldura și cresc încet la frig. Temperaturile calde și stabile îi ajută să-și păstreze florile.","en":"Peppers like warmth and grow slowly when cold. Stable warm temperatures help them keep their flowers."},"learn":{"start":{"ro":"Semănați în interior cu 8–10 săptămâni înainte de răsădire, la 22–28 °C; răsar încet.","en":"Sow indoors 8–10 weeks before transplanting, at 22–28 °C; they germinate slowly."},"care":{"ro":"Feriți de curent rece, sprijiniți plantele încărcate și udați constant, fără exces.","en":"Keep away from cold draughts, support heavy plants, and water steadily without overdoing it."},"harvest":{"ro":"Recoltați verzi sau după ce capătă culoarea finală, tăind codița cu foarfeca.","en":"Pick green or once they reach their final colour, cutting the stalk with scissors."}},"symptoms":[{"sign":{"ro":"Cad florile sau fructele mici","en":"Flowers or small fruit dropping"},"cause":{"ro":"Adesea căldură, frig sau stres hidric","en":"Often heat, cold, or water stress"},"action":{"ro":"Verificați temperatura aerului și umiditatea solului și mențineți-le stabile.","en":"Check air temperature and soil moisture, and keep both steady."}},{"sign":{"ro":"Pete pale, ca de hârtie, pe fructe","en":"Pale, papery patches on fruit"},"cause":{"ro":"Posibilă arsură solară de la lumina directă intensă","en":"Possible sunscald from intense direct light"},"action":{"ro":"Adăugați umbrire ușoară și păstrați frunzișul peste fructe.","en":"Add light shade and keep enough leaf cover over the fruit."}},{"sign":{"ro":"Pată închisă, adâncită, la vârful fructului","en":"Dark, sunken patch at the end of the fruit"},"cause":{"ro":"Putregaiul apical, legat de obicei de udarea neregulată","en":"Blossom end rot, usually linked to uneven watering"},"action":{"ro":"Mențineți umiditatea solului constantă.","en":"Keep soil moisture steady."}}],"scientificName":"Capsicum annuum","airTemperature":{"min":17,"max":30},"soilPh":{"min":5.5,"max":6.8}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('cucumber', '{"id":"cucumber","emoji":"🥒","category":"fruiting","name":{"ro":"Castravete","en":"Cucumber"},"typeExample":{"ro":"Cornichon","en":"Gherkin"},"ecocrop":{"code":817,"scientificName":"Cucumis sativus","tempOptimal":{"min":18,"max":32},"tempAbsolute":{"min":6,"max":38},"phOptimal":{"min":6,"max":7.5},"phAbsolute":{"min":4.5,"max":8.7},"cycleDays":{"min":40,"max":180},"killingTemp":null,"light":"very bright"},"soilMoisture":{"min":45,"max":75},"humidity":{"min":60,"max":80},"soilTemperature":{"min":20,"max":28},"soilEc":{"min":1,"max":2.5},"irrigationBaseHours":18,"economics":{"yieldKgPerCycle":4,"cycleDays":110,"pricePerKg":6},"tip":{"ro":"Castraveții beau multă apă și cresc repede: verificați solul zilnic, mai ales în zilele calde.","en":"Cucumbers drink a lot and grow fast, so check the soil daily, especially on warm days."},"learn":{"start":{"ro":"Semănați direct sau în ghivece mici, la peste 20 °C în sol; nu suportă frigul.","en":"Sow directly or in small pots with soil above 20 °C; they cannot take cold."},"care":{"ro":"Conduceți pe sfoară sau spalier și udați des, la bază, cu apă care nu e rece.","en":"Train up a string or trellis and water often, at the base, with water that is not cold."},"harvest":{"ro":"Recoltați des, cât fructele sunt tinere și ferme; recolta deasă stimulează producția.","en":"Harvest often while fruit is young and firm; frequent picking keeps them producing."}},"symptoms":[{"sign":{"ro":"Pulbere albă pe frunze","en":"White powder on the leaves"},"cause":{"ro":"Probabil făinare, favorizată de aer umed și circulație slabă","en":"Probably powdery mildew, favoured by humid air and poor airflow"},"action":{"ro":"Aerisiți, distanțați plantele și îndepărtați frunzele afectate.","en":"Ventilate, space plants out, and remove affected leaves."}},{"sign":{"ro":"Fructe amare sau strâmbe","en":"Bitter or misshapen fruit"},"cause":{"ro":"Adesea stres hidric sau temperaturi foarte mari","en":"Often water stress or very high temperatures"},"action":{"ro":"Udați mai constant și reduceți căldura în orele de vârf.","en":"Water more consistently and reduce heat during peak hours."}}],"scientificName":"Cucumis sativus","airTemperature":{"min":18,"max":32},"light":{"min":400,"max":800},"soilPh":{"min":6,"max":7.5}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('eggplant', '{"id":"eggplant","emoji":"🍆","category":"fruiting","name":{"ro":"Vânătă","en":"Eggplant"},"typeExample":{"ro":"Black Beauty","en":"Black Beauty"},"ecocrop":{"code":1965,"scientificName":"Solanum melongena","tempOptimal":{"min":20,"max":35},"tempAbsolute":{"min":9,"max":40},"phOptimal":{"min":5.5,"max":6.8},"phAbsolute":{"min":4.3,"max":8.5},"cycleDays":{"min":70,"max":120},"killingTemp":null,"light":"very bright"},"soilMoisture":{"min":40,"max":65},"humidity":{"min":50,"max":70},"soilTemperature":{"min":20,"max":28},"soilEc":{"min":1,"max":2.5},"irrigationBaseHours":24,"economics":{"yieldKgPerCycle":3,"cycleDays":120,"pricePerKg":8},"tip":{"ro":"Vinetele au nevoie de cea mai multă căldură dintre legumele de seră; frigul le oprește creșterea.","en":"Eggplants need the most warmth of the greenhouse vegetables; cold stops their growth."},"learn":{"start":{"ro":"Semănați în interior cu 8–10 săptămâni înainte de răsădire, la 25–30 °C.","en":"Sow indoors 8–10 weeks before transplanting, at 25–30 °C."},"care":{"ro":"Sprijiniți plantele, udați regulat și fertilizați moderat când apar fructele.","en":"Support the plants, water regularly, and feed moderately once fruit sets."},"harvest":{"ro":"Recoltați când coaja e lucioasă; coaja mată arată că fructul e trecut.","en":"Pick while the skin is glossy; a dull skin means the fruit is past its best."}},"symptoms":[{"sign":{"ro":"Frunze cu multe găurițe mici","en":"Leaves with many small holes"},"cause":{"ro":"Probabil puricii de pământ","en":"Probably flea beetles"},"action":{"ro":"Inspectați frunzele și folosiți plasă sau capcane lipicioase.","en":"Inspect the leaves and use netting or sticky traps."}},{"sign":{"ro":"Florile cad fără fructe","en":"Flowers dropping without fruit"},"cause":{"ro":"Frig, căldură excesivă sau polenizare slabă","en":"Cold, excessive heat, or poor pollination"},"action":{"ro":"Verificați temperatura și scuturați ușor florile pentru polenizare.","en":"Check temperature and gently shake flowers to help pollination."}}],"scientificName":"Solanum melongena","airTemperature":{"min":20,"max":35},"light":{"min":400,"max":800},"soilPh":{"min":5.5,"max":6.8}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
