":6.8}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('lettuce', '{"id":"lettuce","emoji":"🥬","category":"leafy","name":{"ro":"Salată","en":"Lettuce"},"typeExample":{"ro":"Salată căpățână","en":"Butterhead"},"ecocrop":{"code":1313,"scientificName":"Lactuca sativa var. capitata","tempOptimal":{"min":12,"max":21},"tempAbsolute":{"min":5,"max":30},"phOptimal":{"min":6,"max":7},"phAbsolute":{"min":4.2,"max":7.5},"cycleDays":{"min":35,"max":85},"killingTemp":0,"light":"clear skies"},"scientificName":"Lactuca sativa","soilMoisture":{"min":45,"max":70},"humidity":{"min":50,"max":70},"soilTemperature":{"min":12,"max":20},"soilEc":{"min":0.6,"max":1.6},"irrigationBaseHours":24,"economics":{"yieldKgPerCycle":0.35,"cycleDays":60,"pricePerKg":10},"tip":{"ro":"Salata preferă răcoarea: la căldură trage în floare și devine amară.","en":"Lettuce prefers cool conditions; in heat it bolts and turns bitter."},"learn":{"start":{"ro":"Semănați eșalonat, la 2–3 săptămâni, la 10–20 °C; semințele au nevoie de lumină ca să răsară.","en":"Sow every 2–3 weeks at 10–20 °C; the seeds need light to germinate."},"care":{"ro":"Mențineți solul reavăn și umbriți ușor în zilele fierbinți.","en":"Keep the soil evenly moist and give light shade on hot days."},"harvest":{"ro":"Recoltați dimineața, când frunzele sunt crocante.","en":"Harvest in the morning, when the leaves are crisp."}},"symptoms":[{"sign":{"ro":"Tulpina se alungește, frunzele devin amare","en":"Stem stretching up and leaves turning bitter"},"cause":{"ro":"Tragere în floare din cauza căldurii sau a zilelor lungi","en":"Bolting from heat or long days"},"action":{"ro":"Recoltați imediat și semănați soiuri rezistente la căldură.","en":"Harvest now and sow heat-tolerant types."}},{"sign":{"ro":"Marginile frunzelor se înnegresc","en":"Leaf edges turning brown"},"cause":{"ro":"Posibil deficit de calciu sau udare neregulată","en":"Possible calcium shortage or uneven watering"},"action":{"ro":"Udați constant și evitați excesul de îngrășământ.","en":"Water evenly and avoid overfeeding."}}],"airTe