max":20},"soilPh":{"min":6,"max":7.5}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('cabbage', '{"id":"cabbage","emoji":"🥬","category":"leafy","name":{"ro":"Varză","en":"Cabbage"},"typeExample":{"ro":"Varză creață","en":"Savoy"},"ecocrop":{"code":554,"scientificName":"Brassica oleracea var. capitata","tempOptimal":{"min":15,"max":24},"tempAbsolute":{"min":7,"max":32},"phOptimal":{"min":6,"max":7.5},"phAbsolute":{"min":5,"max":8.3},"cycleDays":{"min":60,"max":200},"killingTemp":-1,"light":"clear skies"},"soilMoisture":{"min":45,"max":70},"humidity":{"min":60,"max":80},"soilTemperature":{"min":12,"max":22},"soilEc":{"min":1,"max":2.5},"irrigationBaseHours":30,"economics":{"yieldKgPerCycle":1.5,"cycleDays":120,"pricePerKg":3},"tip":{"ro":"Varza are nevoie de apă constantă: udarea neregulată după perioade uscate face căpățânile să crape.","en":"Cabbage needs steady water; irregular watering after dry spells makes heads split."},"learn":{"start":{"ro":"Semănați în răsadniță, apoi răsădiți la 4–6 frunze, la 40–50 cm distanță.","en":"Sow in a seedbed, then transplant at 4–6 leaves, 40–50 cm apart."},"care":{"ro":"Udați uniform, mușuroiți ușor și protejați de omizi cu plasă fină.","en":"Water evenly, earth up lightly, and protect from caterpillars with fine netting."},"harvest":{"ro":"Recoltați când căpățâna e tare și compactă.","en":"Harvest when the head is firm and compact."}},"symptoms":[{"sign":{"ro":"Frunze roase, cu găuri mari","en":"Leaves chewed with large holes"},"cause":{"ro":"Probabil omizi de fluture alb al verzei","en":"Probably cabbage white caterpillars"},"action":{"ro":"Verificați dosul frunzelor și folosiți plasă anti-insecte.","en":"Check under the leaves and use insect netting."}},{"sign":{"ro":"Căpățâna crapă","en":"Head splitting open"},"cause":{"ro":"Absorbție bruscă de apă după secetă","en":"Sudden water uptake after a dry spell"},"action":{"ro":"Udați constant și recoltați căpățânile mature.","en":"Water steadily and harvest mature heads."}}],"scientificName":"Brassica oleracea var. capitata","airTemperature":{"min":15,"max":24},"light":{"min":300,"max":650},"soilPh":{"min":6,"max":7.5}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
  ('carrot', '{"id":"carrot","emoji":"🥕","category":"root","name":{"ro":"Morcov","en":"Carrot"},"typeExample":{"ro":"Nantes","en":"Nantes"},"ecocrop":{"code":871,"scientificName":"Daucus carota","tempOptimal":{"min":15,"max":24},"tempAbsolute":{"min":3,"max":30},"phOptimal":{"min":5.8,"max":6.8},"phAbsolute":{"min":4.2,"max":8.7},"cycleDays":{"min":40,"max":150},"killingTemp":0,"light":"clear skies"},"soilMoisture":{"min":40,"max":65},"humidity":{"min":50,"max":70},"soilTemperature":{"min":12,"max":22},"soilEc":{"min":0.6,"max":1.6},"irrigationBaseHours":36,"economics":{"yieldKgPerCycle":0.12,"cycleDays":95,"pricePerKg":4},"tip":{"ro":"Morcovul are nevoie de sol afânat, fără pietre; solul tasat face rădăcini strâmbe.","en":"Carrots need loose, stone-free soil; compacted soil makes forked roots."},"learn":{"start":{"ro":"Semănați direct, superficial, și mențineți solul umed până la răsărire (2–3 săptămâni).","en":"Sow directly and shallowly, and keep the soil moist until they come up (2–3 weeks)."},"care":{"ro":"Răriți la 4–5 cm și udați rar dar profund.","en":"Thin to 4–5 cm apart and water deeply but less often."},"harvest":{"ro":"Recoltați când umărul rădăcinii are 2–3 cm diametru.","en":"Harvest when the top of the root is 2–3 cm across."}},"symptoms":[{"sign":{"ro":"Rădăcini despicate sau ramificate","en":"Split or forked roots"},"cause":{"ro":"Sol tasat sau udare neregulată","en":"Compacted soil or irregular watering"},"action":{"ro":"Afânați solul și udați uniform.","en":"Loosen the soil and water evenly."}},{"sign":{"ro":"Galerii în rădăcini","en":"Tunnels in the roots"},"cause":{"ro":"Probabil musca morcovului","en":"Probably carrot fly"},"action":{"ro":"Acoperiți cu plasă fină și evitați să rupeți frunzele la rărit.","en":"Cover with fine mesh and avoid bruising leaves when thinning."}}],"scientificName":"Daucus carota","airTemperature":{"min":15,"max":24},"light":{"min":300,"max":650},"soilPh":{"min":5.8,"max":6.8}}'::jsonb, 'FAO EcoCrop database (gaez.fao.org/pages/ecocrop), via the OpenCLIM EcoCrop_DB.csv export'),
